type Bit is Data:
  BitZero{}
  BitOne{}
type Pair is Data:
  Pair{left: Bit, right: Bit}
def choose(x: Bit, v: Bit) -> Pair:
  match x:
    case BitZero{}: Pair{BitZero{}, BitZero{}}
    case BitOne{}: Pair{BitZero{}, BitZero{}}
    case other: Pair{v, BitZero{}}

